# C ABI contract matching the Rust `#[repr(C)]` exports.
# The Rust module is expected to expose:
#   typedef struct {
#       double alpha;
#       double beta;
#       double gamma;
#       uint8_t seasonal_mode;  // 0=ADDITIVE, 1=MULTIPLICATIVE
#       uint32_t season_length;
#   } hw_config_t;
#
#   typedef struct hw_model hw_model_t;
#
#   hw_model_t* hw_fit(const double* data, size_t len, const hw_config_t* cfg);
#   void hw_forecast(const hw_model_t* model, size_t horizon, double* out);
#   void hw_free(hw_model_t* model);
#   const char* hw_last_error(void);


@dataclass(frozen=True)
class HWConfig:
    """Python mirror of the Rust `hw_config_t` struct."""
    alpha: float
    beta: float
    gamma: float
    seasonal_mode: int  # 0=ADDITIVE, 1=MULTIPLICATIVE
    season_length: int

    def validate(self) -> None:
        """Validate config parameters against documented constraints."""
        if not (0.0 <= self.alpha <= 1.0):
            raise ValueError(f"alpha must be in [0,1], got {self.alpha}")
        if not (0.0 <= self.beta <= 1.0):
            raise ValueError(f"beta must be in [0,1], got {self.beta}")
        if not (0.0 <= self.gamma <= 1.0):
            raise ValueError(f"gamma must be in [0,1], got {self.gamma}")
        if self.seasonal_mode not in (0, 1):
            raise ValueError(f"seasonal_mode must be 0 or 1, got {self.seasonal_mode}")
        if self.season_length < 1:
            raise ValueError(f"season_length must be >= 1, got {self.season_length}")


class HoltWintersError(RuntimeError):
    """Raised when the Rust library returns an error condition."""


class HoltWintersLibrary:
    """Thin ctypes wrapper around the compiled Rust shared library."""

    _lib: Optional[ctypes.CDLL] = None

    # ctypes type definitions
    _CONFIG_T = ctypes.Structure
    _CONFIG_T._fields_ = [
        ("alpha", ctypes.c_double),
        ("beta", ctypes.c_double),
        ("gamma", ctypes.c_double),
        ("seasonal_mode", ctypes.c_uint8),
        ("season_length", ctypes.c_uint32),
    ]

    _MODEL_PTR = ctypes.c_void_p

    @classmethod
    def _locate_library(cls) -> Path:
        """Locate the compiled shared library."""
        env_path = os.environ.get("HOLT_WINTERS_LIB")
        if env_path:
            p = Path(env_path)
            if p.exists():
                return p
            raise FileNotFoundError(
                f"HOLT_WINTERS_LIB points to non-existent path: {env_path}"
            )

        # Default search paths relative to crate root
        crate_root = Path(__file__).resolve().parents[2]  # tests/ -> crate root
        system = platform.system()
        if system == "Linux":
            candidates = [
                crate_root / "target" / "release" / "libholt_winters.so",
                crate_root / "target" / "debug" / "libholt_winters.so",
            ]
        elif system == "Darwin":
            candidates = [
                crate_root / "target" / "release" / "libholt_winters.dylib",
                crate_root / "target" / "debug" / "libholt_winters.dylib",
            ]
        elif system == "Windows":
            candidates = [
                crate_root / "target" / "release" / "holt_winters.dll",
                crate_root / "target" / "debug" / "holt_winters.dll",
            ]
        else:
            raise OSError(f"Unsupported platform: {system}")

        for candidate in candidates:
            if candidate.exists():
                return candidate

        raise FileNotFoundError(
            "Could not locate libholt_winters shared library. "
            "Build with `cargo build --release` and set HOLT_WINTERS_LIB if needed."
        )

    @classmethod
    def get_library(cls) -> ctypes.CDLL:
        """Load and cache the shared library."""
        if cls._lib is not None:
            return cls._lib

        lib_path = cls._locate_library()
        lib = ctypes.CDLL(str(lib_path))

        # Configure function signatures
        lib.hw_fit.restype = cls._MODEL_PTR
        lib.hw_fit.argtypes = [
            ctypes.POINTER(ctypes.c_double),
            ctypes.c_size_t,
            ctypes.POINTER(cls._CONFIG_T),
        ]

        lib.hw_forecast.restype = None
        lib.hw_forecast.argtypes = [
            cls._MODEL_PTR,
            ctypes.c_size_t,
            ctypes.POINTER(ctypes.c_double),
        ]

        lib.hw_free.restype = None
        lib.hw_free.argtypes = [cls._MODEL_PTR]

        lib.hw_last_error.restype = ctypes.c_char_p
        lib.hw_last_error.argtypes = []

        cls._lib = lib
        return lib

    @classmethod
    def fit(
        cls, data: Sequence[float], config: HWConfig
    ) -> ctypes.c_void_p:
        """Fit the Holt-Winters model to data."""
        config.validate()
        lib = cls.get_library()

        data_arr = (ctypes.c_double * len(data))(*data)
        cfg = cls._CONFIG_T(
            alpha=config.alpha,
            beta=config.beta,
            gamma=config.gamma,
            seasonal_mode=config.seasonal_mode,
            season_length=config.season_length,
        )

        model_ptr = lib.hw_fit(data_arr, len(data), ctypes.byref(cfg))
        if not model_ptr:
            err = lib.hw_last_error()
            raise HoltWintersError(
                err.decode("utf-8") if err else "Unknown error during fit"
            )
        return model_ptr

    @classmethod
    def forecast(cls, model_ptr: ctypes.c_void_p, horizon: int) -> List[float]:
        """Generate forecasts from a fitted model."""
        lib = cls.get_library()
        out = (ctypes.c_double * horizon)()
        lib.hw_forecast(model_ptr, horizon, out)
        return list(out)

    @classmethod
    def free(cls, model_ptr: ctypes.c_void_p) -> None:
        """Release model memory."""
        if model_ptr:
            lib = cls.get_library()
            lib.hw_free(model_ptr)


