class TestStatisticalCorrectness:
    """Validate against analytically known series."""

    def test_linear_trend_forecast(self, hw_lib, linear_trend_data, default_config):
        """Forecast of a linear trend should continue the line."""
        model = HoltWintersLibrary.fit(linear_trend_data, default_config)
        try:
            horizon = 10
            forecast = HoltWintersLibrary.forecast(model, horizon)
            # Last training point
            last_x = len(linear_trend_data) - 1
            expected_last = 2.0 * last_x + 10.0
            # Forecast should continue with slope ~2.0
            for i, val in enumerate(forecast):
                expected = expected_last + 2.0 * (i + 1)
                assert abs(val - expected) < 2.0, (
                    f"Forecast[{i}] = {val}, expected ~{expected}"
                )
        finally:
            HoltWintersLibrary.free(model)

    def test_pure_seasonal_forecast(self, hw_lib, pure_seasonal_data, default_config):
        """Forecast of pure seasonality should repeat the seasonal pattern."""
        model = HoltWintersLibrary.fit(pure_seasonal_data, default_config)
        try:
            horizon = 24  # Two full seasons
            forecast = HoltWintersLibrary.forecast(model, horizon)
            # The pattern should repeat with period 12
            for i in range(12):
                assert abs(forecast[i] - forecast[i + 12]) < 0.5, (
                    f"Seasonal mismatch at offset {i}: "
                    f"{forecast[i]} vs {forecast[i+12]}"
                )
        finally:
            HoltWintersLibrary.free(model)

    def test_seasonal_trend_forecast(self, hw_lib, seasonal_trend_data, default_config):
        """Forecast should capture both trend and seasonality."""
        model = HoltWintersLibrary.fit(seasonal_trend_data, default_config)
        try:
            horizon = 12
            forecast = HoltWintersLibrary.forecast(model, horizon)
            # Forecast should be positive and increasing (trend dominates)
            assert all(f > 0 for f in forecast)
            assert forecast[-1] > forecast[0]
        finally:
            HoltWintersLibrary.free(model)

    def test_constant_series_forecast(self, hw_lib, constant_data, default_config):
        """Forecast of a constant series should remain constant."""
        model = HoltWintersLibrary.fit(constant_data, default_config)
        try:
            horizon = 20
            forecast = HoltWintersLibrary.forecast(model, horizon)
            for val in forecast:
                assert abs(val - 42.0) < 1e-6, f"Expected 42.0, got {val}"
        finally:
            HoltWintersLibrary.free(model)

    def test_multiplicative_seasonality(self, hw_lib, seasonal_trend_data):
        """Multiplicative mode should handle multiplicative seasonality."""
        config = HWConfig(
            alpha=0.3, beta=0.1, gamma=0.2,
            seasonal_mode=1, season_length=12,
        )
        model = HoltWintersLibrary.fit(seasonal_trend_data, config)
        try:
            horizon = 12
            forecast = HoltWintersLibrary.forecast(model, horizon)
            assert all(f > 0 for f in forecast), "Multiplicative forecasts must be positive"
        finally:
            HoltWintersLibrary.free(model)

    def test_forecast_length_matches_horizon(self, hw_lib, linear_trend_data, default_config):
        """Forecast output length must equal requested horizon."""
        model = HoltWintersLibrary.fit(linear_trend_data, default_config)
        try:
            for horizon in [1, 5, 50]:
                forecast = HoltWintersLibrary.forecast(model, horizon)
                assert len(forecast) == horizon
        finally:
            HoltWintersLibrary.free(model)


