class TestEdgeCaseHardening:
    """Verify robustness against boundary conditions and malformed input."""

    def test_zero_length_input(self, hw_lib, default_config):
        """Zero-length input should raise a clear error."""
        with pytest.raises(HoltWintersError):
            HoltWintersLibrary.fit([], default_config)

    def test_single_element_input(self, hw_lib, default_config):
        """Single-element input should either work or raise a clear error."""
        try:
            model = HoltWintersLibrary.fit([1.0], default_config)
            HoltWintersLibrary.free(model)
        except HoltWintersError as e:
            assert "length" in str(e).lower() or "data" in str(e).lower()

    def test_season_length_one(self, hw_lib, linear_trend_data):
        """season_length=1 should be treated as no seasonality."""
        config = HWConfig(
            alpha=0.3, beta=0.1, gamma=0.0,
            seasonal_mode=0, season_length=1,
        )
        model = HoltWintersLibrary.fit(linear_trend_data, config)
        try:
            forecast = HoltWintersLibrary.forecast(model, 5)
            assert len(forecast) == 5
        finally:
            HoltWintersLibrary.free(model)

    def test_boundary_smoothing_parameters(self, hw_lib, linear_trend_data):
        """alpha=1.0 should give full weight to latest observation."""
        config = HWConfig(
            alpha=1.0, beta=0.0, gamma=0.0,
            seasonal_mode=0, season_length=12,
        )
        model = HoltWintersLibrary.fit(linear_trend_data, config)
        try:
            forecast = HoltWintersLibrary.forecast(model, 1)
            # With alpha=1, beta=0, forecast should be last value
            assert abs(forecast[0] - linear_trend_data[-1]) < 1e-6
        finally:
            HoltWintersLibrary.free(model)

    def test_alpha_zero(self, hw_lib, linear_trend_data):
        """alpha=0.0 should give full weight to initial level."""
        config = HWConfig(
            alpha=0.0, beta=0.0, gamma=0.0,
            seasonal_mode=0, season_length=12,
        )
        model = HoltWintersLibrary.fit(linear_trend_data, config)
        try:
            forecast = HoltWintersLibrary.forecast(model, 1)
            # With alpha=0, forecast should be initial value
            assert abs(forecast[0] - linear_trend_data[0]) < 1e-6
        finally:
            HoltWintersLibrary.free(model)

    def test_large_input_no_panic(self, hw_lib, default_config):
        """Large input should not cause panic or memory issues."""
        large_data = np.random.RandomState(42).randn(10000) * 10 + 100
        model = HoltWintersLibrary.fit(large_data.tolist(), default_config)
        try:
            forecast = HoltWintersLibrary.forecast(model, 100)
            assert len(forecast) == 100
            assert all(np.isfinite(f) for f in forecast)
        finally:
            HoltWintersLibrary.free(model)

    def test_nan_input_rejected(self, hw_lib, default_config):
        """NaN input should raise a clear error."""
        with pytest.raises(HoltWintersError):
            HoltWintersLibrary.fit([1.0, float("nan"), 3.0], default_config)

    def test_inf_input_rejected(self, hw_lib, default_config):
        """Infinite input should raise a clear error."""
        with pytest.raises(HoltWintersError):
            HoltWintersLibrary.fit([1.0, float("inf"), 3.0], default_config)

    def test_deterministic_output(self, hw_lib, linear_trend_data, default_config):
        """Same input + config must produce identical output."""
        model1 = HoltWintersLibrary.fit(linear_trend_data, default_config)
        model2 = HoltWintersLibrary.fit(linear_trend_data, default_config)
        try:
            f1 = HoltWintersLibrary.forecast(model1, 10)
            f2 = HoltWintersLibrary.forecast(model2, 10)
            assert f1 == f2
        finally:
            HoltWintersLibrary.free(model1)
            HoltWintersLibrary.free(model2)


