class TestResourceBudget:
    """Verify O(1) memory and O(n) time characteristics."""

    def test_memory_constant_across_sizes(self, hw_lib, default_config):
        """Memory usage should not grow with input size (O(1) model state)."""
        import resource
        import subprocess
        import sys

        # Run in subprocess to isolate memory measurement
        code = """
import sys, os
sys.path.insert(0, {tests_dir!r})
from test_holt_winters import HoltWintersLibrary, HWConfig
import numpy as np

config = HWConfig(0.3, 0.1, 0.2, 0, 12)
for n in [100, 1000, 10000]:
    data = np.random.RandomState(42).randn(n).tolist()
    model = HoltWintersLibrary.fit(data, config)
    HoltWintersLibrary.free(model)
""".format(tests_dir=repr(str(Path(__file__).parent)))

        result = subprocess.run(
            [sys.executable, "-c", code],
            capture_output=True, text=True, timeout=30,
        )
        assert result.returncode == 0, f"Subprocess failed: {result.stderr}"

    def test_time_linear_scaling(self, hw_lib, default_config):
        """Fit time should scale roughly linearly with input size."""
        import time

        sizes = [100, 500, 1000]
        times = []
        for n in sizes:
            data = np.random.RandomState(42).randn(n).tolist()
            start = time.perf_counter()
            model = HoltWintersLibrary.fit(data, default_config)
            HoltWintersLibrary.free(model)
            times.append(time.perf_counter() - start)

        # Check that time doesn't grow super-linearly (allow 3x slack)
        if times[0] > 0:
            ratio = times[-1] / times[0]
            size_ratio = sizes[-1] / sizes[0]
            assert ratio < size_ratio * 3, (
                f"Time scaling suspicious: {times} for sizes {sizes}"
            )

    def test_forecast_memory_constant(self, hw_lib, linear_trend_data, default_config):
        """Forecast memory should be O(horizon), not O(n)."""
        model = HoltWintersLibrary.fit(linear_trend_data, default_config)
        try:
            # Small and large horizons should both work
            for horizon in [1, 1000]:
                forecast = HoltWintersLibrary.forecast(model, horizon)
                assert len(forecast) == horizon
        finally:
            HoltWintersLibrary.free(model)


