class TestEndToEnd:
    """Full pipeline: fit -> forecast -> validate against known series."""

    def test_airline_passengers_style(self, hw_lib):
        """Classic multiplicative seasonal dataset pattern."""
        # Generate a series similar to airline passengers (trend * seasonality)
        months = np.arange(144)  # 12 years
        trend = 100 + 2.0 * months
        seasonal = 1.0 + 0.4 * np.sin(2 * np.pi * months / 12)
        data = trend * seasonal

        config = HWConfig(
            alpha=0.3, beta=0.1, gamma=0.2,
            seasonal_mode=1, season_length=12,
        )
        model = HoltWintersLibrary.fit(data.tolist(), config)
        try:
            horizon = 12
            forecast = HoltWintersLibrary.forecast(model, horizon)
            # Forecast should continue the upward trend
            assert forecast[-1] > forecast[0]
            # Forecast should be positive
            assert all(f > 0 for f in forecast)
            # Forecast should be in a reasonable range
            last_value = data[-1]
            assert all(abs(f - last_value) < last_value * 0.5 for f in forecast)
        finally:
            HoltWintersLibrary.free(model)

    def test_forecast_accuracy_metric(self, hw_lib, seasonal_trend_data, default_config):
        """Forecast accuracy should be reasonable on held-out data."""
        # Split data: train on first 80%, test on last 20%
        split = int(len(seasonal_trend_data) * 0.8)
        train = seasonal_trend_data[:split]
        test = seasonal_trend_data[split:]

        model = HoltWintersLibrary.fit(train.tolist(), default_config)
        try:
            horizon = len(test)
            forecast = HoltWintersLibrary.forecast(model, horizon)
            # Calculate MAPE (Mean Absolute Percentage Error)
            mape = np.mean(np.abs((test - forecast) / test)) * 100
            # Allow generous tolerance for this synthetic data
            assert mape < 20.0, f"MAPE too high: {mape:.2f}%"
        finally:
            HoltWintersLibrary.free(model)


