class TestPerformanceBenchmarks:
    """Performance benchmarks (run with `pytest --benchmark`)."""

    def test_fit_1000_points(self, hw_lib, benchmark, default_config):
        """Benchmark fitting 1000 points."""
        data = np.random.RandomState(42).randn(1000).tolist()

        def _fit():
            model = HoltWintersLibrary.fit(data, default_config)
            HoltWintersLibrary.free(model)

        benchmark(_fit)

    def test_forecast_100_horizon(self, hw_lib, benchmark, linear_trend_data, default_config):
        """Benchmark forecasting 100 steps."""
        model = HoltWintersLibrary.fit(linear_trend_data.tolist(), default_config)
        try:
            def _forecast():
                HoltWintersLibrary.forecast(model, 100)
            benchmark(_forecast)
        finally:
            HoltWintersLibrary.free(model)


